SELECT ROUND(SUM(order_revenue), 2) AS revenue
FROM mart_order_summary
WHERE status = 'Complete';

SELECT ROUND((SUM(returned_units) * 1.0) / SUM(units_sold), 4) AS return_rate
FROM mart_product_sales
WHERE STRFTIME('%Y', order_date) = '2022';

SELECT COUNT(DISTINCT user_id) AS active_users
FROM mart_user_summary
WHERE recency <= 90;

SELECT CAST(COUNT(CASE WHEN recency > 90 THEN 1 END) AS REAL) * 100.0 / COUNT(*) AS churn_rate
FROM mart_user_summary
WHERE frequency IS NOT NULL;
